const GLOSSARY = [
  { key: "austrias", pattern: "\\b(?:Austrias|Habsburgo|Habsburgos)\\b", title: "Los Austrias", definition: "La dinastía de los Habsburgo que gobernó la monarquía hispánica entre los siglos XVI y XVIII. En Madrid dejó el trazado y muchos edificios del entorno de Plaza Mayor." },
  { key: "real-sitio", pattern: "\\bReal sitio\\b", title: "Real sitio", definition: "Lugar vinculado a la Corona, normalmente con palacio, jardines y edificios de servicio." },
  { key: "cornisa", pattern: "\\bcornisa\\b", title: "Cornisa", definition: "Borde elevado de una meseta o terraza. La cornisa de la Almudena asoma sobre el Campo del Moro y la Casa de Campo." },
  { key: "almudena", pattern: "\\bAlmudena\\b", title: "Almudena", definition: "Nombre de la patrona de Madrid. La catedral está dedicada a Santa María la Real de la Almudena." },
  { key: "almadraba", pattern: "\\balmadraba\\b", title: "Almadraba", definition: "Arte tradicional de pesca del atún rojo mediante redes fijas en la costa. El término aparece en las cartas del mercado." },
  { key: "gourmet", pattern: "\\bGourmet Experience\\b", title: "Gourmet Experience", definition: "Espacio gastronómico de El Corte Inglés con puestos de comida y una terraza panorámica sobre Callao y Gran Vía." },
  { key: "zbedep", pattern: "\\bZBEDEP\\b", title: "ZBEDEP", definition: "Zona de Bajas Emisiones de Especial Protección. El vehículo ECO puede acceder, pero conviene comprobar siempre las reglas y el parking elegido." },
  { key: "colegiata", pattern: "\\bcolegiata\\b", title: "Colegiata", definition: "Iglesia atendida por un colegio de canónigos, sin ser necesariamente sede de un obispo." }
].map((entry) => ({ ...entry, matcher: new RegExp(`^(?:${entry.pattern})$`, "iu") }));
const GLOSSARY_PATTERN = new RegExp(GLOSSARY.map((entry) => entry.pattern).sort((a, b) => b.length - a.length).join("|"), "giu");
function glossaryMarkup(value = "") {
  return String(value).replace(GLOSSARY_PATTERN, (match) => { const entry = GLOSSARY.find((item) => item.matcher.test(match)); return entry ? `<button class="glossary-term" type="button" data-glossary="${entry.key}" aria-haspopup="dialog">${match}</button>` : match; });
}

