const KEYS = { visited: "madrid-centro-tour:visited-stops", provider: "madrid-centro-tour:map-provider", optional: "madrid-centro-tour:include-gallery" };
const read = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
const write = (key, value) => localStorage.setItem(key, JSON.stringify(value));
const state = { visited: read(KEYS.visited, []), provider: read(KEYS.provider, "ask"), optional: read(KEYS.optional, false), active: 0 };
const $ = (selector, root = document) => root.querySelector(selector);
function mainStops() { const stops = ROUTE_ORDER.map((id) => STOPS.find((stop) => stop.id === id)).filter(Boolean); if (state.optional) { const palaceIndex = stops.findIndex((stop) => stop.id === 6); stops.splice(palaceIndex + 1, 0, GALLERY); } return stops; }
function renumberStops() { document.querySelectorAll("[data-stop-id]").forEach((article, index) => { const number = String(index + 1).padStart(2, "0"); const numberElement = $(".stop__number", article); const tagElement = $(".stop__tag", article); if (numberElement) numberElement.textContent = number; if (tagElement && !article.classList.contains("stop--optional")) tagElement.textContent = `Parada ${number}`; }); }

function googlePlace(stop) { return `https://www.google.com/maps/search/?api=1&query=${stop.coordinates.lat},${stop.coordinates.lng}`; }
function googleDirections(from, to) { const origin = from ? `&origin=${from.coordinates.lat},${from.coordinates.lng}` : ""; return `https://www.google.com/maps/dir/?api=1${origin}&destination=${to.coordinates.lat},${to.coordinates.lng}&travelmode=walking`; }
function osmandPoint(stop) { return `https://osmand.net/map/?pin=${stop.coordinates.lat},${stop.coordinates.lng}#18/${stop.coordinates.lat}/${stop.coordinates.lng}`; }
function osmandNavigate(to) { return `https://osmand.net/map/navigate/?finish=${to.coordinates.lat},${to.coordinates.lng}&type=osmand&profile=pedestrian`; }
function mapUrl(action, stop, next) { if (state.provider === "osmand") return action === "place" ? osmandPoint(stop) : osmandNavigate(next || stop); return action === "place" ? googlePlace(stop) : googleDirections(null, next || stop); }
function imageFigure(stop) { const image = IMAGE_URLS[stop.id] || stop.image; if (!image) return `<div class="stop__image stop__image--fallback" data-mark="${String(stop.id).padStart(2, "0")}" aria-hidden="true"></div>`; const credit = stop.imageCredit ? ` · Foto: <a href="${stop.imageCredit.url}" target="_blank" rel="noreferrer">${stop.imageCredit.author}</a>` : ""; return `<figure class="stop__image"><img src="${image}" alt="${stop.alt}" loading="lazy" width="${stop.imageWidth || 1600}" height="${stop.imageHeight || 1067}" data-parallax /><figcaption>${stop.name}${credit}</figcaption></figure>`; }
function stopTemplate(stop, index, visible) {
  const next = visible[index + 1]; const isVisited = state.visited.includes(stop.id); const last = !next;
  const timelineItems = stop.timeline || []; const timeline = timelineItems.length ? `<div class="stop__timeline"><span class="stop__timeline-label">Hitos en el tiempo</span>${timelineItems.map((item) => `<div><strong>${glossaryMarkup(item.date)}</strong><span><b>${glossaryMarkup(item.label)}</b>${glossaryMarkup(item.text)}</span></div>`).join("")}</div>` : "";
  const details = (stop.details || []).map((detail) => `<aside class="stop__detail stop__detail--${detail.kind}"><strong>${glossaryMarkup(detail.label)}</strong><h3>${glossaryMarkup(detail.title)}</h3><p>${glossaryMarkup(detail.text)}</p>${detail.extra ? `<p>${glossaryMarkup(detail.extra)}</p>` : ""}${detail.prompt ? `<p class="stop__detail-prompt">${glossaryMarkup(detail.prompt)}</p>` : ""}</aside>`).join("");
  const nextBlock = next ? `<div class="stop__next"><small>Siguiente · ${next.duration}</small><a href="#parada-${next.id}">${next.name} <span aria-hidden="true">↘</span></a></div>` : `<div class="stop__next"><small>Fin del circuito</small><span>Volver al parking de Plaza Mayor</span></div>`;
  const navigateLabel = last ? "Volver al parking" : "Caminar a la siguiente";
  return `<article class="stop${stop.optional ? " stop--optional" : ""}${isVisited ? " is-visited" : ""}" id="parada-${stop.id}" data-stop-id="${stop.id}"><div class="stop__grid"><div class="stop__copy"><p class="stop__number" aria-hidden="true">${String(stop.id).padStart(2, "0")}</p><p class="stop__tag">${stop.optional ? "Parada opcional" : `Parada ${String(stop.id).padStart(2, "0")}`}</p><h2>${glossaryMarkup(stop.name)}</h2><p class="stop__subtitle">${glossaryMarkup(stop.subtitle)}</p><p class="stop__description">${glossaryMarkup(stop.description)}</p>${timeline}${details}<div class="stop__meta"><span>◷ ${stop.duration}</span><span>◌ ${stop.price}</span></div><aside class="stop__curiosity"><strong>Dato curioso</strong><p>${glossaryMarkup(stop.curiosity)}</p></aside><div class="stop__actions"><button class="button button--accent" type="button" data-navigate="${stop.id}">${navigateLabel} <span aria-hidden="true">↗</span></button><button class="button button--outline" type="button" data-place="${stop.id}">Ver este lugar</button><button class="button button--outline" type="button" data-copy="${stop.id}">Copiar coordenadas</button><button class="visit-toggle" type="button" data-visit="${stop.id}" aria-pressed="${isVisited}"><span class="visit-toggle__box" aria-hidden="true"></span>${isVisited ? "Visitada" : "Marcar como visitada"}</button></div><div class="stop__sources"><a class="source-link" href="${stop.source}" target="_blank" rel="noreferrer">Información oficial ↗</a>${stop.sourceExtra ? `<a class="source-link" href="${stop.sourceExtra}" target="_blank" rel="noreferrer">${stop.sourceExtraLabel || "Referencia adicional"} ↗</a>` : ""}</div>${nextBlock}</div><div class="stop__media">${imageFigure(stop)}</div></div></article>`;
}
function render() { const visible = mainStops(); $("[data-stops]").innerHTML = visible.map((stop, index) => stopTemplate(stop, index, visible)).join(""); renumberStops(); $("[data-progress]").textContent = `${visible.filter((stop) => state.visited.includes(stop.id)).length} / ${visible.length}`; $("[data-optional-toggle]").textContent = state.optional ? "Quitar Galería opcional" : "Añadir Galería de las Colecciones Reales"; bindStopEvents(); observeStops(); updateParallax(); }
function openProviderDialog(action, stopId) { const dialog = $("[data-map-dialog]"); dialog.dataset.action = action; dialog.dataset.stopId = stopId; if (typeof dialog.showModal === "function") dialog.showModal(); else dialog.setAttribute("open", ""); }
function launchMap(action, stopId) { const visible = mainStops(); const stop = visible.find((item) => item.id === Number(stopId)); if (!stop) return; const index = visible.indexOf(stop); const next = visible[index + 1]; if (action === "return") { const parking = STOPS[0]; if (state.provider === "ask") return openProviderDialog("return", parking.id); window.location.href = mapUrl("navigate", stop, parking); return; } if (action === "navigate" && !next) { if (state.provider === "ask") return openProviderDialog("return", stop.id); window.location.href = mapUrl("navigate", stop, STOPS[0]); return; } if (state.provider === "ask") return openProviderDialog(action, stop.id); window.location.href = mapUrl(action, stop, next); }
function bindStopEvents() { document.querySelectorAll("[data-visit]").forEach((button) => button.addEventListener("click", () => { const id = Number(button.dataset.visit); const at = state.visited.indexOf(id); if (at < 0) state.visited.push(id); else state.visited.splice(at, 1); write(KEYS.visited, state.visited); render(); document.getElementById(`parada-${id}`)?.scrollIntoView({ behavior: "smooth", block: "start" }); })); document.querySelectorAll("[data-place], [data-navigate]").forEach((button) => button.addEventListener("click", () => launchMap(button.dataset.place ? "place" : "navigate", button.dataset.place || button.dataset.navigate))); document.querySelectorAll("[data-copy]").forEach((button) => button.addEventListener("click", async () => { const stop = mainStops().find((item) => item.id === Number(button.dataset.copy)); if (!stop) return; const coordinates = `${stop.coordinates.lat}, ${stop.coordinates.lng}`; try { await navigator.clipboard.writeText(coordinates); } catch { window.prompt("Copia estas coordenadas", coordinates); } const original = button.textContent; button.textContent = "Coordenadas copiadas"; window.setTimeout(() => { button.textContent = original; }, 1800); })); }
function observeStops() { const observer = new IntersectionObserver((entries) => entries.forEach((entry) => { if (!entry.isIntersecting) return; state.active = Number(entry.target.dataset.stopId); const stop = mainStops().find((item) => item.id === state.active); $("[data-current-label]").textContent = stop?.shortName || "Ruta"; }), { rootMargin: "-35% 0px -55%", threshold: 0 }); document.querySelectorAll("[data-stop-id]").forEach((section) => observer.observe(section)); }
let parallaxFrame; function updateParallax() { parallaxFrame = undefined; if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return; document.querySelectorAll("[data-parallax]").forEach((image) => { const box = image.closest(".stop__media").getBoundingClientRect(); const distance = (box.top + box.height / 2 - window.innerHeight / 2) / window.innerHeight; image.style.setProperty("--parallax", `${Math.max(-5, Math.min(5, distance * -3))}%`); }); }
window.addEventListener("scroll", () => { if (!parallaxFrame) parallaxFrame = requestAnimationFrame(updateParallax); }, { passive: true });
document.querySelector("[data-settings]").addEventListener("click", () => openProviderDialog("settings", 0));
document.querySelector("[data-optional-toggle]").addEventListener("click", () => { state.optional = !state.optional; write(KEYS.optional, state.optional); render(); });
document.querySelectorAll("[data-provider]").forEach((button) => button.addEventListener("click", () => { const dialog = $("[data-map-dialog]"); if (button.dataset.provider === "copy") { dialog.close(); return; } state.provider = button.dataset.provider; write(KEYS.provider, state.provider); const action = dialog.dataset.action; const stopId = dialog.dataset.stopId; dialog.close(); if (["place", "navigate", "return"].includes(action)) launchMap(action, stopId); }));
let lastGlossaryTrigger; function openGlossary(key, trigger) { const entry = GLOSSARY.find((item) => item.key === key); const dialog = $("[data-glossary-dialog]"); if (!entry) return; lastGlossaryTrigger = trigger; $("[data-glossary-title]", dialog).textContent = entry.title; $("[data-glossary-definition]", dialog).textContent = entry.definition; if (typeof dialog.showModal === "function") dialog.showModal(); else dialog.setAttribute("open", ""); }
document.addEventListener("click", (event) => { const trigger = event.target instanceof Element ? event.target.closest("[data-glossary]") : null; if (trigger) openGlossary(trigger.dataset.glossary, trigger); });
const glossaryDialog = $("[data-glossary-dialog]"); glossaryDialog.addEventListener("click", (event) => { if (event.target === event.currentTarget) event.currentTarget.close(); }); glossaryDialog.addEventListener("close", () => { lastGlossaryTrigger?.focus(); lastGlossaryTrigger = undefined; });
$("[data-download-gpx]").addEventListener("click", () => { const waypoints = mainStops().map((stop) => `  <wpt lat="${stop.coordinates.lat}" lon="${stop.coordinates.lng}"><name>${stop.id}. ${stop.name}</name><desc>${stop.subtitle}</desc></wpt>`).join("\n"); const gpx = `<?xml version="1.0" encoding="UTF-8"?>\n<gpx version="1.1" creator="Madrid centro paseo a pie" xmlns="http://www.topografix.com/GPX/1/1">\n${waypoints}\n</gpx>`; const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob([gpx], { type: "application/gpx+xml" })); link.download = state.optional ? "madrid-centro-ruta-ampliada.gpx" : "madrid-centro-ruta.gpx"; link.click(); URL.revokeObjectURL(link.href); });
$("[data-map-dialog]").addEventListener("click", (event) => { if (event.target === event.currentTarget) event.currentTarget.close(); });
const topbar = $("[data-topbar]"); window.addEventListener("scroll", () => topbar.classList.toggle("is-scrolled", window.scrollY > 20), { passive: true });
